/**
 * Repos view: lists git repositories discovered under the version's custom
 * addons folder and toggles their membership in the active project.
 */
import { RepoModel, normalizeBranchMode } from "./models/repo";
import * as vscode from "vscode";
import { findRepositories, getWorkspacePath, normalizePath, stripSettings } from './utils';
import { SettingsStore } from './settingsStore';
import { readUpgradeConfig, refuseDuringUpgrade } from './upgrade';
import { VersionsService } from './versionsService';
import * as path from 'path';
import * as fs from 'fs';
import { SortPreferences } from './sortPreferences';
import { getDefaultSortOption } from './sortOptions';
import { getRepoBranch } from './services/branches';
import { invalidateModuleDiscoveryCache, invalidateRepositoryDiscoveryCache } from './services/runtimeCache';
import { BaseTreeProvider } from './views/baseTreeProvider';
import { selectedIcon, unselectedIcon } from './views/icons';

interface RepoEntry {
    name: string;
    path: string;
    isSelected: boolean;
    branch: string | null;
    isGitRepo: boolean;
    repoModel?: RepoModel;
    fsCreatedAt: number;
}

async function mapWithConcurrency<T, R>(items: T[], limit: number, worker: (item: T) => Promise<R>): Promise<R[]> {
    if (items.length === 0) {
        return [];
    }

    const normalizedLimit = Math.max(1, limit);
    const results: R[] = new Array(items.length);
    let cursor = 0;

    const runNext = async (): Promise<void> => {
        const index = cursor++;
        if (index >= items.length) {
            return;
        }
        results[index] = await worker(items[index]);
        await runNext();
    };

    const workers = Array.from({ length: Math.min(normalizedLimit, items.length) }, () => runNext());
    await Promise.all(workers);
    return results;
}


export class RepoTreeProvider extends BaseTreeProvider<vscode.TreeItem> {

    constructor(_context: vscode.ExtensionContext, private sortPreferences: SortPreferences) {
        super();
    }
    getTreeItem(element: vscode.TreeItem): vscode.TreeItem {
        return element;
    }
    async getChildren(_element?: any): Promise<vscode.TreeItem[] | undefined> {
        const result = await SettingsStore.getSelectedProject();
        if (!result) {
            return [];
        }

        const { project } = result;
        const workspacePath = getWorkspacePath();
        if (!workspacePath) {
            return [];
        }

        const repos: RepoModel[] = project.repos;
        
        // Get settings from active version
        const versionsService = VersionsService.getInstance();
        const settings = await versionsService.getActiveVersionSettings();
        const customAddonsPath = normalizePath(settings.customAddonsPath);

        // Empty lists fall through to the view's welcome content, which
        // points at the version's custom addons folder setting.
        if (!fs.existsSync(customAddonsPath)) {
            return [];
        }

        const devsRepos = findRepositories(customAddonsPath);
        if (devsRepos.length === 0 || !repos) {
            return [];
        }

        const repoEntries = await mapWithConcurrency(devsRepos, 6, async repo => {
            const existingRepo = repos.find(r => r.name === repo.name);
            let branch: string | null = null;
            const isGitRepo = fs.existsSync(path.join(repo.path, '.git'));
            if (isGitRepo) {
                try {
                    branch = await getRepoBranch(repo.path);
                } catch {
                    branch = null;
                }
            }
            let fsCreatedAt = 0;
            try {
                const stats = fs.statSync(repo.path);
                fsCreatedAt = stats.birthtimeMs || stats.ctimeMs || 0;
            } catch {
                fsCreatedAt = 0;
            }
            return {
                name: repo.name,
                path: repo.path,
                isSelected: !!existingRepo,
                branch,
                isGitRepo,
                repoModel: existingRepo,
                fsCreatedAt
            };
        });

        const sortId = this.sortPreferences.get('repoSelector', getDefaultSortOption('repoSelector'));
        repoEntries.sort((a, b) => this.compareRepos(a, b, sortId));

        return repoEntries.map(entry => {
            const treeItem = new vscode.TreeItem(entry.name);
            treeItem.iconPath = entry.isSelected ? selectedIcon : unselectedIcon;
            treeItem.tooltip = new vscode.MarkdownString([
                `**${entry.name}**${entry.isSelected ? ' (in project)' : ''}`,
                `**Path:** ${entry.path}`,
                entry.branch ? `**Branch:** ${entry.branch}` : '',
                entry.isGitRepo ? '' : '**Type:** addons folder (not a git repository)'
            ].filter(Boolean).join('\n\n'));
            treeItem.id = entry.path;
            treeItem.description = entry.isGitRepo ? (entry.branch ?? '') : 'addons folder';
            treeItem.contextValue = normalizeBranchMode(entry.repoModel?.branchMode) === 'worktree'
                ? 'repoPerBranch'
                : 'repo';
            // Carried for the shared reveal/copy-path/terminal commands (extractUri).
            (treeItem as vscode.TreeItem & { uri?: vscode.Uri }).uri = vscode.Uri.file(entry.path);
            treeItem.command = {
                command: 'repoSelector.selectRepo',
                title: 'Select Module',
                arguments: [{ isSelected: entry.isSelected, path: entry.path, name: entry.name }]
            };
            return treeItem;
        });
    }

    private compareRepos(a: RepoEntry, b: RepoEntry, sortId: string): number {
        const selectedDelta = Number(b.isSelected) - Number(a.isSelected);
        if (selectedDelta !== 0) {
            return selectedDelta;
        }

        switch (sortId) {
            case 'repo:name:asc':
                return a.name.localeCompare(b.name);
            case 'repo:name:desc':
                return b.name.localeCompare(a.name);
            case 'repo:created:newest':
                return this.getRepoTimestamp(b) - this.getRepoTimestamp(a);
            case 'repo:created:oldest':
                return this.getRepoTimestamp(a) - this.getRepoTimestamp(b);
            case 'repo:branch:asc':
                return (a.branch ?? '').localeCompare(b.branch ?? '') || a.name.localeCompare(b.name);
            case 'repo:branch:desc':
                return (b.branch ?? '').localeCompare(a.branch ?? '') || a.name.localeCompare(b.name);
            default:
                return a.name.localeCompare(b.name);
        }
    }

    private getRepoTimestamp(entry: RepoEntry): number {
        if (entry.repoModel?.addedAt) {
            const added = new Date(entry.repoModel.addedAt).getTime();
            if (!isNaN(added)) {
                return added;
            }
        }
        return entry.fsCreatedAt ?? 0;
    }
}

export async function selectRepo(event: any) {
    const selectedRepo = event;
    const result = await SettingsStore.getSelectedProject();
    if (!result) {
        return;
    }

    const { data, project } = result;
    const repoInProject = project.repos.find((repo: RepoModel) => repo.name === selectedRepo.name);

    if (!repoInProject) {
        project.repos.push(new RepoModel(selectedRepo.name, selectedRepo.path, selectedRepo.isSelected));
    } else {
        // Dropping a repository the upgrade runs on orphans its per-branch
        // copies and the branch mapping on both databases. Adding one is fine.
        const upgradeConfig = readUpgradeConfig(project);
        if (upgradeConfig.involvesRepo(selectedRepo.name)
            && refuseDuringUpgrade(upgradeConfig, `"${selectedRepo.name}" cannot be removed from the project`)) {
            return;
        }
        project.repos = project.repos.filter((repo: RepoModel) => repo.name !== selectedRepo.name);
    }

    invalidateModuleDiscoveryCache();
    invalidateRepositoryDiscoveryCache();
    await SettingsStore.saveWithoutComments(stripSettings(data));
}
